export function verifyProfileProof(profile,proof){
  assert.deepEqual(profile,[[0,0,0],[4,0,0],[4,0,3],[2,0,4],[0,0,3]]);assert.equal(proof.method,'raw-native-edge-endpoints-and-volume');assert.equal(proof.unit,'metres-relative-to-origin-feet');assert.ok(Array.isArray(proof.vertices)&&proof.vertices.length>=10&&proof.vertices.length<=10000&&proof.vertices.every(point=>Array.isArray(point)&&point.length===3&&point.every(Number.isFinite)));
  const area=Math.abs(profile.reduce((sum,point,index)=>{const next=profile[(index+1)%profile.length];return sum+point[0]*next[2]-next[0]*point[2];},0))/2;near(area,14,'Independent polygon shoelace area');near(proof.manualShoelaceAreaMetres2,area,'Recorded profile area');near(proof.thicknessMetres,.2,'Fixture profile thickness');near(proof.nativeVolumeMetres3,area*.2,'Raw native profile volume');
  for(const point of profile)assert.ok(proof.vertices.some(native=>Math.abs(native[0]-point[0])<2e-6&&Math.abs(native[2]-point[2])<2e-6),'Actual native edge endpoints must contain the complete nonrectangular profile');const ys=proof.vertices.map(point=>point[1]);near(Math.max(...ys)-Math.min(...ys),.2,'Native profile full thickness',2e-6);for(const native of proof.vertices)assert.ok(native[0]>=-2e-6&&native[0]<=4+2e-6&&native[2]>=-2e-6&&native[2]<=4+2e-6);return{area,volume:area*.2};
}

