const samePath=(left,right)=>typeof left==='string'&&typeof right==='string'&&path.resolve(left).toLowerCase()===path.resolve(right).toLowerCase();
function child(parent,value){const full=path.resolve(value),base=path.resolve(parent);assert.ok(full.toLowerCase().startsWith(base.toLowerCase()+path.sep),'Evidence path escapes its explicit boundary');return full;}
function basename(value){assert.equal(typeof value,'string');assert.ok(value&&value!=='.'&&value!=='..'&&!/[\\/\u0000:]/u.test(value),'Plain artifact basename required');return value;}
async function exists(value){try{await access(value);return true;}catch(error){if(error.code==='ENOENT')return false;throw error;}}
async function bytes(value){const file=path.resolve(value),info=await stat(file);assert.ok(info.isFile()&&info.size<=268435456,'Bounded regular evidence file required');assert.ok(samePath(await realpath(file),file),'Reparse evidence file refused');return readFile(file);}
async function json(value){const raw=await bytes(value);return{data:JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw).replace(/^\ufeff/u,'')),sha256:digest(raw),bytes:raw.length,path:path.resolve(value)};}
async function matches(value,sha256,length){assert.match(sha256,HASH);const raw=await bytes(value);assert.equal(digest(raw),sha256,`Evidence bytes changed: ${value}`);if(length!==undefined)assert.equal(raw.length,length,`Evidence length changed: ${value}`);return{path:path.resolve(value),sha256,bytes:raw.length};}

