  const registrationText=new TextDecoder('utf-8',{fatal:true}).decode(await bytes(prepared.registrationCandidatePath));assert.ok(registrationText.includes('<FullClassName>BrightVision.CivilWallJoinHostAcceptance.App</FullClassName>')&&registrationText.includes('<AllowLoadingIntoExistingSession>False</AllowLoadingIntoExistingSession>'));
